import {drawingMap} from './map-views.js';
import {migrateCombinedDrawing} from './data/combined-maps.js';
import {placementAliases,correctDungeon} from './data/placement-corrections.js';
export const COLORS=['#e43969','#387bff','#30c99a','#bc78f5','#f5a442','#35bfd9','#e477cf','#b3cc55'];
export const uid=()=>globalThis.crypto.randomUUID();
// Migrate only labels generated by the original Russian UI; preserve custom text.
export function englishDefaultLabel(name){
  if(name==='\u041d\u043e\u0432\u044b\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442')return 'New route';
  if(name==='\u0418\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442')return 'Imported route';
  return typeof name==='string'?name.replace(/^\u041f\u0443\u043b\u043b (\d+)$/,'Pull $1'):name;
}
export function pullColor(index){
  if(index<COLORS.length)return COLORS[index];
  const h=(index*137.508)%360,s=.78,l=.6;
  const channel=n=>{const k=(n+h/30)%12,a=s*Math.min(l,1-l);return Math.round(255*(l-a*Math.max(-1,Math.min(k-3,9-k,1)))).toString(16).padStart(2,'0');};
  return '#'+channel(0)+channel(8)+channel(4);
}
export function newPull(index=0){return {id:uid(),name:`Pull ${index+1}`,customName:false,color:pullColor(index),enemies:[],note:''};}
export function hasCustomPullName(pull){return pull.customName===true||!/^Pull \d+$/.test(englishDefaultLabel(pull.name)||'');}
export function renamePull(pull,name,index){
  const trimmed=name.trim();
  pull.customName=trimmed!==''&&(trimmed!==pull.name||hasCustomPullName(pull));
  pull.name=trimmed||`Pull ${index+1}`;
}
export function movePull(route,from,to){
  if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=route.pulls.length||to>=route.pulls.length||from===to)return;
  // Colors belong to list positions; names and encounter contents follow their pull.
  const colors=route.pulls.map(p=>p.color);
  route.pulls.splice(to,0,route.pulls.splice(from,1)[0]);
  route.pulls.forEach((pull,index)=>{
    if(!hasCustomPullName(pull))pull.name=`Pull ${index+1}`;
    pull.color=colors[index];
  });
}
export const defaultModifiers=()=>({empowered:{active:false,enemies:[]},ghorn:{active:false,packId:null},witch:{active:false,packId:null}});
export const modifierId=kind=>`modifier:${kind}`;
export function applyModifierPresets(route,dungeon,presets){
  const row=presets?.dungeons?.[dungeon.id];if(!row)return;
  route.modifiers??=defaultModifiers();
  route.modifiers.empowered={active:route.modifiers.empowered.active&&row.empowered.length>0,enemies:[...row.empowered]};
  for(const kind of ['ghorn','witch']){
    const preset=row[kind],active=route.modifiers[kind].active;
    route.modifiers[kind]=preset?{active,packId:preset.packId,replacedEnemies:[...preset.replacedEnemies]}:{active:false,packId:null};
    if(!preset){for(const pull of route.pulls)pull.enemies=pull.enemies.filter(id=>id!==modifierId(kind));route.excluded=route.excluded.filter(id=>id!==modifierId(kind));}
  }
}
export function toggleModifier(route,kind){
  const mod=route.modifiers[kind];mod.active=!mod.active;
  if(kind!=='empowered'&&mod.active&&!route.pulls.some(p=>p.enemies.includes(modifierId(kind)))){
    const pull=route.pulls.find(p=>p.enemies.some(id=>mod.replacedEnemies?.includes(id)));
    if(pull)assignEnemies(route,pull.id,[modifierId(kind)],{toggle:false});
  }
}
export function clearRoute(route){route.pulls=[];route.drawings=[];route.excluded=[];route.shadow=false;route.modifiers=defaultModifiers();}
export function hasRouteChanges(route,saved){
  const content=r=>JSON.stringify({
    name:r.name,shadow:r.shadow,
    modifiers:['empowered','ghorn','witch'].map(kind=>{const m=r.modifiers?.[kind];return m?.active?{active:true,enemies:m.enemies,packId:m.packId,replacedEnemies:m.replacedEnemies}:{active:false};}),
    pulls:r.pulls.map(p=>({name:p.name,customName:hasCustomPullName(p),color:p.color,enemies:p.enemies,note:p.note||''})),
    drawings:r.drawings.map(d=>({mapId:d.mapId,kind:d.kind,color:d.color,width:d.kind==='line'?(d.width??3):null,text:d.text||'',points:d.points})),excluded:r.excluded,
  });
  const baseline=saved||{name:/^Route [1-9]\d*$/.test(route.name)?route.name:'New route',shadow:false,modifiers:defaultModifiers(),pulls:route.pulls.length?[newPull()]:[],drawings:[],excluded:[]};
  return content(route)!==content(baseline);
}
export function newRoute(dungeon,buildId,name='Route 1'){return {version:2,buildId,id:uid(),dungeonId:dungeon.id,name,shadow:false,modifiers:defaultModifiers(),pulls:[newPull()],drawings:[],excluded:[]};}
export function enemyScore(enemy,shadow,reference,empowered=false){
  const base=enemy?.dungeonScore;
  if(!Number.isFinite(base)) return null;
  const row=reference?.enemies.find(r=>r.name===enemy.name&&r.normal===base);
  const raw=row?row.shadow:base;
  return shadow?raw*(empowered?3:1):empowered?3*raw+(base-raw):base;
}
export function replacedIds(route,dungeon){
  const result=new Set();
  for(const kind of ['ghorn','witch']){const mod=route.modifiers?.[kind];if(!mod?.active)continue;for(const id of mod.replacedEnemies||dungeon.enemies.filter(p=>p.packId===mod.packId).map(p=>p.placementId))result.add(id);}
  return result;
}
export function effectivePositions(route,dungeon){
  const hidden=replacedIds(route,dungeon),result=correctDungeon(dungeon).enemies.filter(p=>!hidden.has(p.placementId));
  for(const kind of ['ghorn','witch']){
    const mod=route.modifiers?.[kind];if(!mod?.active||!mod.packId)continue;
    const pack=dungeon.enemies.filter(p=>mod.replacedEnemies?mod.replacedEnemies.includes(p.placementId):p.packId===mod.packId),first=pack.find(p=>p.mapPosition);
    const mapped=pack.filter(p=>p.mapPosition&&p.mapImageId===first?.mapImageId);
    if(!pack.length)continue;
    const world=mapped.filter(p=>p.worldPosition);
    const worldPosition=world.length?Object.fromEntries(['x','y','z'].map(k=>[k,world.reduce((s,p)=>s+p.worldPosition[k],0)/world.length])):null;
    result.push({id:modifierId(kind),placementId:modifierId(kind),packId:modifierId(kind),modifier:kind,worldPosition,mapMembers:mapped,mapImageId:first?.mapImageId||null,mapPosition:mapped.length?{x:mapped.reduce((s,p)=>s+p.mapPosition.x,0)/mapped.length,y:mapped.reduce((s,p)=>s+p.mapPosition.y,0)/mapped.length}:null});
  }
  return result;
}
export function placementScore(pos,enemy,route,reference){
  if(!enemy?.isBoss&&route.excluded.includes(pos.placementId))return 0;
  if(pos.modifier)return 20;
  return enemyScore(enemy,route.shadow,reference,!enemy?.isBoss&&route.modifiers?.empowered?.active&&route.modifiers.empowered.enemies.includes(pos.placementId));
}
export function setReplacement(route,kind,packId,dungeon,enemies){
  if(!['ghorn','witch'].includes(kind))throw new Error('Invalid modifier.');
  const pack=dungeon.enemies.filter(p=>p.packId===packId);
  if(!pack.length||pack.some(p=>enemies.get(p.id)?.isBoss))throw new Error('Choose a non-boss pack.');
  const other=kind==='ghorn'?'witch':'ghorn';
  if(route.modifiers[other].packId===packId)throw new Error('This pack already has a replacement.');
  route.modifiers[kind]={active:true,packId};
  // A changed replacement is deliberately unassigned until selected on the map.
  for(const p of route.pulls)p.enemies=p.enemies.filter(id=>id!==modifierId(kind));
  route.excluded=route.excluded.filter(id=>id!==modifierId(kind));
}
export function shadowTarget(dungeon){return ['Heart of Tuzari','The Heart of Tuzari','Ransack of Drakheim','Wraithtide Vault',"Cithrel's Fall"].includes(dungeon.name)?90:60;}
export function orbCount(score,dungeon){return Math.max(0,Math.floor(score/dungeon.requiredScore*(shadowTarget(dungeon)-1)+.85));}
export function shadowTimeline(route,dungeon,enemies,reference){
  let cumulative=0,previous=0;
  return route.pulls.map(p=>{const s=scorePull(p,dungeon,enemies,route,reference);cumulative+=s.orbScore;const total=orbCount(cumulative,dungeon),orbs=total-previous,spawns=Math.min(shadowTarget(dungeon)/30,Math.floor(total/30))-Math.min(shadowTarget(dungeon)/30,Math.floor(previous/30));previous=total;return {orbs,total,spawns};});
}
export function scorePull(pull,dungeon,enemies,route,reference){
  const positions=new Map(effectivePositions(route,dungeon).map(e=>[e.placementId,e]));
  const inactive=new Set([...replacedIds(route,dungeon),...['ghorn','witch'].filter(k=>!route.modifiers?.[k]?.active).map(modifierId)]);
  const aliases=placementAliases[dungeon.id]||{},canonical=id=>aliases[id]||id;
  const excluded=new Set(route.excluded.map(canonical));
  let score=0,orbScore=0,unknown=0,bosses=0,count=0;
  for(const id of new Set(pull.enemies.map(canonical))){
    if(inactive.has(id))continue;
    const pos=positions.get(id);if(!pos){unknown++;continue;}
    const enemy=enemies.get(pos.id);const value=!enemy?.isBoss&&excluded.has(id)?0:placementScore(pos,enemy,route,reference);
    if(value===null)unknown++;else {score+=value;if(!pos.modifier)orbScore+=value;}
    if(enemy?.isBoss)bosses++;count++;
  }
  return {score,orbScore,unknown,bosses,count,percent:dungeon.requiredScore>0?score/dungeon.requiredScore*100:null};
}
export function scoreRoute(route,dungeon,enemies,reference){
  return scorePull({enemies:route.pulls.flatMap(p=>p.enemies)},dungeon,enemies,route,reference);
}
export function assignEnemies(route,pullId,ids,{toggle=true}={}){
  const pull=route.pulls.find(p=>p.id===pullId);if(!pull)return;
  const chosen=new Set(ids), remove=toggle&&ids.length>0&&ids.every(id=>pull.enemies.includes(id));
  for(const p of route.pulls)p.enemies=p.enemies.filter(id=>!chosen.has(id));
  if(!remove)pull.enemies.push(...chosen);
}
export function validateRoute(value,dungeons,enemies){
  if(!value||![1,2].includes(value.version))throw new Error('Unsupported format. Use a route JSON file from this planner (version 1 or 2).');
  const dungeon=dungeons.find(d=>d.id===value.dungeonId);
  if(!dungeon)throw new Error('This dungeon is not available in the current dataset.');
  if(!Array.isArray(value.pulls)||value.pulls.length>500)throw new Error('Invalid pull list.');
  const aliases=placementAliases[dungeon.id]||{},canonical=id=>aliases[id]||id;
  const original=new Set(dungeon.enemies.map(e=>e.placementId)),known=new Set([...original,...['ghorn','witch'].map(modifierId)]),seen=new Set(),rawSeen=new Set(),pullIds=new Set();
  const modifiers=defaultModifiers();
  if(value.modifiers!==undefined){
    if(!value.modifiers||typeof value.modifiers!=='object')throw new Error('Invalid modifiers.');
    const emp=value.modifiers.empowered;
    if(emp){if(!Array.isArray(emp.enemies)||!emp.enemies.every(id=>original.has(id)))throw new Error('Invalid empowered enemies.');modifiers.empowered={active:emp.active===true,enemies:[...new Set(emp.enemies)]};}
    for(const k of ['ghorn','witch']){const m=value.modifiers[k];if(!m)continue;if(m.packId!==null&&!dungeon.enemies.some(p=>p.packId===m.packId))throw new Error('Invalid replacement pack.');if(m.active&&!m.packId)throw new Error('Choose a replacement pack.');if(m.packId&&enemies&&dungeon.enemies.some(p=>p.packId===m.packId&&enemies.get(p.id)?.isBoss))throw new Error('Cannot replace a boss pack.');modifiers[k]={active:m.active===true,packId:m.packId};}
    if(modifiers.ghorn.packId&&modifiers.ghorn.packId===modifiers.witch.packId)throw new Error('Replacement packs must be different.');
    for(const k of ['ghorn','witch']){const ids=value.modifiers[k]?.replacedEnemies;if(ids===undefined)continue;if(!Array.isArray(ids)||!ids.length||!ids.every(id=>original.has(id)))throw new Error('Invalid replacement enemies.');if(enemies&&dungeon.enemies.some(p=>ids.includes(p.placementId)&&enemies.get(p.id)?.isBoss))throw new Error('Cannot replace a boss pack.');modifiers[k].replacedEnemies=[...new Set(ids)];}
    if(modifiers.ghorn.replacedEnemies?.some(id=>modifiers.witch.replacedEnemies?.includes(id)))throw new Error('Replacement enemies must be different.');
  }
  for(const k of ['ghorn','witch'])if(!modifiers[k].packId)known.delete(modifierId(k));
  const text=(v,max=200)=>typeof v==='string'?v.slice(0,max):'';
  const pulls=value.pulls.map((p,i)=>{
    if(!p||!Array.isArray(p.enemies))throw new Error('Invalid pull.');
    const ids=[];
    for(const rawId of p.enemies){
      if(rawSeen.has(rawId))throw new Error('An enemy is assigned to multiple pulls. Import cancelled.');
      rawSeen.add(rawId);const id=canonical(rawId);
      if(!known.has(id))throw new Error('The route contains enemy placements from another dataset. Import cancelled.');
      if(seen.has(id))continue; // Distinct legacy aliases refer to one encounter.
      seen.add(id);ids.push(id);
    }
    const id=text(p.id)||uid();if(pullIds.has(id))throw new Error('Duplicate pull ID.');pullIds.add(id);
    const name=englishDefaultLabel(text(p.name))||`Pull ${i+1}`;
    return {id,name,customName:hasCustomPullName({...p,name}),color:/^#[0-9a-f]{6}$/i.test(p.color)?p.color:COLORS[i%COLORS.length],enemies:ids,note:text(p.note,4000)};
  });
  if(value.drawings!==undefined&&!Array.isArray(value.drawings))throw new Error('Invalid drawings.');
  const drawings=(value.drawings||[]).slice(0,500).map(d=>{
    if(!d||!Array.isArray(d.points)||d.points.length<1||d.points.length>5000)throw new Error('Invalid drawing.');
    if(!d.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(n=>Number.isFinite(n)&&Math.abs(n)<100000)))throw new Error('Invalid drawing coordinates.');
    d=migrateCombinedDrawing(d,dungeon);
    if(!drawingMap(dungeon,d.mapId)||!d.points.every(p=>p.every(n=>Number.isFinite(n)&&Math.abs(n)<100000)))throw new Error('Invalid drawing.');
    if(['portal','invis'].includes(d.kind)&&d.points.length!==2)throw new Error('Portal and invisibility paths need two endpoints.');
    const kind=['line','portal','invis','note'].includes(d.kind)?d.kind:'line';
    if(kind==='line'&&d.points.length<2)throw new Error('Arrows need two endpoints.');
    const points=kind==='line'?[d.points[0],d.points.at(-1)]:d.points;
    return {id:uid(),mapId:d.mapId,kind,color:/^#[0-9a-f]{6}$/i.test(d.color)?d.color:COLORS[0],...(kind==='line'&&d.width!==undefined?{width:[2,3,5].includes(d.width)?d.width:3}:{}),text:text(d.text,500),points:points.map(p=>[...p])};
  });
  if(value.excluded!==undefined&&(!Array.isArray(value.excluded)||!value.excluded.every(id=>known.has(canonical(id)))))throw new Error('Invalid excluded enemies.');
  const bossIds=new Set(dungeon.enemies.filter(p=>enemies?.get(p.id)?.isBoss).map(p=>p.placementId));
  for(const kind of ['ghorn','witch'])if(enemies?.get(modifierId(kind))?.isBoss)bossIds.add(modifierId(kind));
  return {version:2,id:text(value.id)||uid(),buildId:text(value.buildId),dungeonId:dungeon.id,name:englishDefaultLabel(text(value.name))||'Imported route',shadow:value.shadow===true,modifiers,pulls,drawings,excluded:[...new Set((value.excluded||[]).map(canonical))].filter(id=>!bossIds.has(id))};
}
